css:
.h1-paper {
	font-family: Arial, Helvetica, sans-serif;
	color: #1a1a1a;
	font-size: 10pt;
	line-height: 1.25;
	-webkit-print-color-adjust: exact !important;
	print-color-adjust: exact !important;
}
.h1-page-1 { page-break-after: always; }
.h1-page-2 { page-break-before: always; }
.h1-topbar {
	display: flex;
	align-items: center;
	justify-content: space-between;
	background: #e6e6e6 !important;
	padding: 8px 12px;
	margin: -2px 0 12px;
}
.h1-brand {
	font-size: 13pt;
	font-weight: 800;
	letter-spacing: 0.01em;
}
.h1-brand span { font-weight: 500; }
.h1-mark { width: 72px; height: 72px; }
.h1-title {
	font-size: 16pt;
	font-weight: 800;
	margin: 6px 0 2px;
	line-height: 1.15;
}
.h1-subtitle {
	font-size: 13pt;
	margin: 0 0 14px;
}
.h1-box {
	border: 1px solid #8a8a8a;
	margin-bottom: 14px;
}
.h1-box-head {
	background: #d8d8d8 !important;
	font-weight: 800;
	font-size: 11pt;
	padding: 5px 10px;
	border-bottom: 1px solid #8a8a8a;
}
.h1-grid {
	width: 100%;
	border-collapse: collapse;
	table-layout: fixed;
}
.h1-grid td {
	border: 0 !important;
	padding: 5px 10px !important;
	vertical-align: middle !important;
	background: #fff !important;
}
.h1-lab {
	width: 28%;
	font-weight: 700;
	white-space: nowrap;
}
.h1-val { width: 72%; min-height: 18px; }
.h1-lab-sm { width: 22%; font-weight: 700; }
.h1-val-sm { width: 28%; }
.h1-note {
	text-align: right;
	font-size: 8pt;
	padding: 2px 10px 6px;
	color: #333;
}
.h1-decl {
	padding: 8px 12px 4px;
	font-size: 9.5pt;
}
.h1-decl p { margin: 0 0 8px; }
.h1-sign-row td { height: 58px; }
.h1-uline {
	border-bottom: 1px solid #111;
	min-height: 28px;
	display: block;
}
.h1-footer-bar {
	background: #4d4d4d !important;
	color: #fff !important;
	text-align: center;
	font-size: 8pt;
	padding: 7px 10px;
	margin-top: 18px;
}
.h1-legal {
	display: flex;
	justify-content: space-between;
	font-size: 8pt;
	margin-top: 6px;
	color: #333;
}
.h1-sheet {
	background: #ececec !important;
	border-radius: 10px;
	padding: 12px 12px 16px;
}
.h1-sheet-title {
	font-weight: 800;
	margin: 0 0 8px;
}
.h1-learners, .h1-refer {
	width: 100%;
	border-collapse: collapse;
	table-layout: fixed;
	font-size: 8pt;
	background: #fff;
}
.h1-learners th, .h1-refer th {
	background: #111 !important;
	color: #fff !important;
	font-weight: 700;
	text-align: center;
	text-transform: none !important;
	padding: 5px 4px !important;
	border: 1px solid #111 !important;
	font-size: 7.5pt;
}
.h1-learners td, .h1-refer td {
	border: 1px solid #111 !important;
	padding: 3px 4px !important;
	height: 26px;
	background: #fff !important;
	vertical-align: middle !important;
}
.h1-learners .c-no { width: 6%; text-align: center; }
.h1-learners .c-name { width: 38%; }
.h1-learners .c-dob { width: 14%; text-align: center; }
.h1-learners .c-tel { width: 18%; }
.h1-learners .c-g { width: 14%; text-align: center; }
.h1-learners .c-r { width: 10%; text-align: center; }
.h1-refer-copy {
	font-size: 8.4pt;
	margin: 12px 0 8px;
	text-align: justify;
}
.h1-refer .c-ln { width: 28%; }
.h1-refer .c-cr { width: 28%; }
.h1-refer .c-why { width: 44%; }
.h1-sign-img { max-height: 42px; max-width: 160px; }
.print-format { padding: 0 !important; margin: 0 !important; }
.print-heading, .letter-head, .print-format-letterhead, .letterhead, .letter-head-image { display: none !important; }
.print-format th { text-transform: none !important; }

