{% macro mark() %}
<svg class="h1-mark" viewBox="0 0 80 80" aria-label="Highfield International">
	<circle cx="40" cy="40" r="37" fill="none" stroke="#1a1a1a" stroke-width="2"/>
	<path d="M16 42c6-18 16-28 24-28s18 10 24 28" fill="none" stroke="#1a1a1a" stroke-width="2"/>
	<path d="M18 48c5 14 13 22 22 22s17-8 22-22" fill="none" stroke="#1a1a1a" stroke-width="2"/>
	<text x="40" y="48" text-anchor="middle" font-family="Georgia, serif" font-size="26" font-weight="700">H</text>
</svg>
{% endmacro %}

{% macro input(name, value, extra="") %}
	{% if editable %}
		<input class="h1-input" data-field="{{ name }}" value="{{ value or '' }}" {{ extra }}>
	{% else %}
		{{ value or "" }}
	{% endif %}
{% endmacro %}

<div class="h1-paper h1-page-1">
	<div class="h1-topbar">
		<div class="h1-brand">Highfield <span>EMERGENCY FIRST AID</span></div>
		{{ mark() }}
	</div>
	<div class="h1-title">{{ doc.form_title or "Highfield International Emergency First Aid, AED &amp; CPR all Ages (Level 3 Award)" }}</div>
	<div class="h1-subtitle">Assessment Pack</div>

	<div class="h1-box">
		<div class="h1-box-head">Course Details</div>
		<table class="h1-grid">
			<tr>
				<td class="h1-lab">Centre’s Name:</td>
				<td class="h1-val" colspan="3">{{ input("centre_name", doc.centre_name) }}</td>
			</tr>
			<tr>
				<td class="h1-lab">Venue Address:</td>
				<td class="h1-val" colspan="3">
					{% if editable %}
						<textarea class="h1-input" data-field="venue_address" rows="2">{{ doc.venue_address or "" }}</textarea>
					{% else %}
						{{ doc.venue_address or "" }}
					{% endif %}
				</td>
			</tr>
			<tr>
				<td class="h1-lab-sm">Telephone No:</td>
				<td class="h1-val-sm">{{ input("telephone_no", doc.telephone_no) }}</td>
				<td class="h1-lab-sm">Centre No:</td>
				<td class="h1-val-sm">{{ input("centre_number", doc.centre_number) }}</td>
			</tr>
			<tr>
				<td class="h1-lab">Tutor’s Name:</td>
				<td class="h1-val" colspan="3">{{ input("tutor_name", doc.tutor_name) }}</td>
			</tr>
			<tr>
				<td class="h1-lab">Assessor’s Name*:</td>
				<td class="h1-val" colspan="3">{{ input("assessor_name", doc.assessor_name) }}</td>
			</tr>
			<tr>
				<td class="h1-lab">IQA’s Name**:</td>
				<td class="h1-val" colspan="3">{{ input("iqa_name", doc.iqa_name) }}</td>
			</tr>
			<tr>
				<td class="h1-lab">Course Identification No.:</td>
				<td class="h1-val" colspan="3">{{ input("course_identification_no", doc.course_identification_no) }}</td>
			</tr>
			<tr>
				<td class="h1-lab-sm">Course start date:</td>
				<td class="h1-val-sm">
					{% if editable %}
						<input class="h1-input" type="date" data-field="course_start_date" value="{{ doc.course_start_date or '' }}">
					{% else %}
						{{ frappe.utils.formatdate(doc.course_start_date, "dd/MM/yyyy") if doc.course_start_date else "" }}
					{% endif %}
				</td>
				<td class="h1-lab-sm">Course finish date:</td>
				<td class="h1-val-sm">
					{% if editable %}
						<input class="h1-input" type="date" data-field="course_finish_date" value="{{ doc.course_finish_date or '' }}">
					{% else %}
						{{ frappe.utils.formatdate(doc.course_finish_date, "dd/MM/yyyy") if doc.course_finish_date else "" }}
					{% endif %}
				</td>
			</tr>
			<tr>
				<td class="h1-lab">Blended learning (✓/✘)</td>
				<td class="h1-val" colspan="3">
					{% if editable %}
						<label><input type="checkbox" class="h1-input" data-field="blended_learning" {% if doc.blended_learning %}checked{% endif %}> ✓</label>
					{% else %}
						{{ "✓" if doc.blended_learning else "✘" }}
					{% endif %}
				</td>
			</tr>
		</table>
		<div class="h1-note">*if different from tutor &nbsp; **if sampled</div>
	</div>

	<div class="h1-box">
		<div class="h1-box-head">Assessment Declaration</div>
		<div class="h1-decl">
			<p>I have read and adhered to Highfield’s qualification and assessment requirements.</p>
			<p>I have checked the identification and kept records of all the learners in the course.</p>
			<p>I confirm that the learners listed below have been assessed as per the qualification requirements and the criteria in the <b>Assessment Crib Sheet</b>.</p>
			<p>The learners (if any) who <b>did not pass</b> the qualification, have been identified with a <b>refer (R)</b> in the list below.</p>
			<p>Where distance learning has been used, evidence of the learner’s distance learning has been retained with the course paperwork.</p>
		</div>
		<table class="h1-grid">
			<tr class="h1-sign-row">
				<td class="h1-lab">Tutor’s Signature:</td>
				<td class="h1-val">
					{% if editable %}
						<div class="h1-sign-wrap">
							{% if doc.tutor_signature %}<img src="{{ doc.tutor_signature }}" class="h1-sign-img">{% endif %}
							<canvas class="h1-sign-canvas" width="260" height="70"></canvas>
							<input type="hidden" class="h1-input" data-field="tutor_signature" value="{{ doc.tutor_signature or '' }}">
							<button type="button" class="h1-sign-clear">Clear</button>
						</div>
					{% elif doc.tutor_signature %}
						<img src="{{ doc.tutor_signature }}" class="h1-sign-img">
					{% else %}
						<span class="h1-uline">&nbsp;</span>
					{% endif %}
				</td>
				<td class="h1-lab-sm">Date:</td>
				<td class="h1-val-sm">
					{% if editable %}
						<input class="h1-input" type="date" data-field="tutor_date" value="{{ doc.tutor_date or '' }}">
					{% else %}
						{{ frappe.utils.formatdate(doc.tutor_date, "dd/MM/yyyy") if doc.tutor_date else "" }}
					{% endif %}
				</td>
			</tr>
			<tr class="h1-sign-row">
				<td class="h1-lab">Assessor’s Signature*:</td>
				<td class="h1-val">
					{% if editable %}
						<div class="h1-sign-wrap">
							{% if doc.assessor_signature %}<img src="{{ doc.assessor_signature }}" class="h1-sign-img">{% endif %}
							<canvas class="h1-sign-canvas" width="260" height="70"></canvas>
							<input type="hidden" class="h1-input" data-field="assessor_signature" value="{{ doc.assessor_signature or '' }}">
							<button type="button" class="h1-sign-clear">Clear</button>
						</div>
					{% elif doc.assessor_signature %}
						<img src="{{ doc.assessor_signature }}" class="h1-sign-img">
					{% else %}
						<span class="h1-uline">&nbsp;</span>
					{% endif %}
				</td>
				<td class="h1-lab-sm">Date:</td>
				<td class="h1-val-sm">
					{% if editable %}
						<input class="h1-input" type="date" data-field="assessor_date" value="{{ doc.assessor_date or '' }}">
					{% else %}
						{{ frappe.utils.formatdate(doc.assessor_date, "dd/MM/yyyy") if doc.assessor_date else "" }}
					{% endif %}
				</td>
			</tr>
		</table>
		<div class="h1-note">*if different from tutor</div>
	</div>

	<div class="h1-footer-bar">A global leader for qualifications, assessment, digital solutions, innovative products, e-learning and customer service.</div>
	<div class="h1-legal"><span>June 2026</span><span>© 2026 Highfield International.</span></div>
</div>

{% for page_rows in pages %}
<div class="h1-paper h1-page-2">
	<div class="h1-topbar">
		<div class="h1-brand">Highfield <span>EMERGENCY FIRST AID</span></div>
		{{ mark() }}
	</div>
	<div class="h1-sheet">
		<div class="h1-sheet-title">Highfield EMERGENCY FIRST AID:</div>
		<table class="h1-learners">
			<thead>
				<tr>
					<th class="c-no"></th>
					<th class="c-name">Learner’s Name (in capitals)</th>
					<th class="c-dob">DOB<br>(DD/MM/YY)</th>
					<th class="c-tel">Tel. No.</th>
					<th class="c-g">Male (M) /<br>Female (F)</th>
					<th class="c-r">Refer (R)</th>
				</tr>
			</thead>
			<tbody>
				{% for row in page_rows %}
				<tr>
					<td class="c-no">{{ row.sr_no or loop.index }}.</td>
					<td class="c-name">
						{% if editable %}
							<input class="h1-input" data-row-field="learner_name" data-sr="{{ row.sr_no or loop.index }}" value="{{ row.learner_name or '' }}">
						{% else %}
							{{ row.learner_name or "" }}
						{% endif %}
					</td>
					<td class="c-dob">
						{% if editable %}
							<input class="h1-input" type="date" data-row-field="date_of_birth" data-sr="{{ row.sr_no or loop.index }}" value="{{ row.date_of_birth or '' }}">
						{% else %}
							{{ frappe.utils.formatdate(row.date_of_birth, "dd/MM/yy") if row.date_of_birth else "" }}
						{% endif %}
					</td>
					<td class="c-tel">
						{% if editable %}
							<input class="h1-input" data-row-field="telephone" data-sr="{{ row.sr_no or loop.index }}" value="{{ row.telephone or '' }}">
						{% else %}
							{{ row.telephone or "" }}
						{% endif %}
					</td>
					<td class="c-g">
						{% if editable %}
							<select class="h1-input" data-row-field="gender" data-sr="{{ row.sr_no or loop.index }}">
								<option value=""></option>
								<option value="M" {% if row.gender == "M" %}selected{% endif %}>M</option>
								<option value="F" {% if row.gender == "F" %}selected{% endif %}>F</option>
							</select>
						{% else %}
							{{ row.gender or "" }}
						{% endif %}
					</td>
					<td class="c-r">
						{% if editable %}
							<input type="checkbox" data-row-field="refer" data-sr="{{ row.sr_no or loop.index }}" {% if row.refer %}checked{% endif %}>
						{% else %}
							{{ "R" if row.refer else "" }}
						{% endif %}
					</td>
				</tr>
				{% endfor %}
			</tbody>
		</table>

		<div class="h1-refer-copy">
			<b>Qualification Outcome “Refer”:</b> To pass this qualification, learners are required to achieve all the practical and knowledge criteria as per the Assessment Crib Sheet. For learners who did not achieve all the practical and knowledge assessment criteria, must be marked as “Refer” on this pack. Assessors must record the rationale for marking a learner as “Refer” in the section below, specifying the criteria that they did not achieve.
		</div>

		<table class="h1-refer">
			<thead>
				<tr>
					<th class="c-ln">Learner Name:</th>
					<th class="c-cr">Practical/Knowledge Criteria:</th>
					<th class="c-why">Record why the learner did not achieve the criteria.</th>
				</tr>
			</thead>
			<tbody>
				{% for row in referrals %}
				<tr>
					<td>
						{% if editable %}
							<input class="h1-input" data-ref-field="learner_name" data-ref="{{ loop.index }}" value="{{ row.learner_name or '' }}">
						{% else %}
							{{ row.learner_name or "" }}
						{% endif %}
					</td>
					<td>
						{% if editable %}
							<input class="h1-input" data-ref-field="criteria" data-ref="{{ loop.index }}" value="{{ row.criteria or '' }}">
						{% else %}
							{{ row.criteria or "" }}
						{% endif %}
					</td>
					<td>
						{% if editable %}
							<input class="h1-input" data-ref-field="rationale" data-ref="{{ loop.index }}" value="{{ row.rationale or '' }}">
						{% else %}
							{{ row.rationale or "" }}
						{% endif %}
					</td>
				</tr>
				{% endfor %}
			</tbody>
		</table>
	</div>
	<div class="h1-footer-bar">A global leader for qualifications, assessment, digital solutions, innovative products, e-learning and customer service.</div>
	<div class="h1-legal"><span>June 2026</span><span>© 2026 Highfield International.</span></div>
</div>
{% endfor %}
